import re
L=open('design/gdd/command-simulation-layer.md',encoding='utf-8').read().split('\n')
hdr=None
for i,l in enumerate(L,1):
    if l.startswith('|'):
        n=len(re.findall(r'(?<!\\)\|',l))
        if hdr is None: hdr=n
        elif n!=hdr: print(i,hdr,n,l[:80])
    else: hdr=None
# duplicate adjacent amendment notes
